    ("h8", "allah", "ضحك الله الليلة أو عجب من فعالكما", "bukhari", 3798, "ضحك الله", ["42:11"], "صفات انفعالية بشرية تُنسب لله."),
    ("h9", "allah", "إن الله لا يملّ حتى تملّوا", "bukhari", 1151, "لا يمل حتى تملوا", ["50:38", "2:255"], "ينسب لله الملل، والقرآن يقول «وما مسّنا من لغوب» و«لا تأخذه سنة ولا نوم»."),
