    ("h12", "allah", "قلوب بني آدم بين إصبعين من أصابع الرحمن", "muslim", 2654, "إصبعين", ["42:11"], "تجسيم صريح بإثبات الأصابع لله."),
    ("h13", "allah", "يأتيهم الله في غير الصورة التي يعرفون", "bukhari", 6573, "الصورة التي يعرفون", ["42:11", "6:103"], "يجعل لله صوراً يتنقّل بينها فينكره الناس ثم يعرفونه."),
